import * as React from "react";

export type SubtitleFrameIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function SubtitleFrameIcon({ size = 20, ...props }: SubtitleFrameIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <rect x="3.5" y="5" width="17" height="14" rx="1.5" /><path d="M7 15h10M9 12.5h6" />
    </svg>
  );
}
